update public.learning_paths
set
  title = 'Religion and Society',
  goal = 'Religion and Society',
  summary = 'Religion and Society examines how religious ideas, practices, institutions, communities, and identities shape social life, and how social forces reshape religion. The course connects sociology of religion, religious studies, politics, law, race and gender studies, migration studies, media studies, ethics, public policy, and global affairs. Students learn to analyze religion as a lived and public phenomenon using theory, empirical evidence, case studies, and current data.',
  data = $resjson${"slug": "religion-and-society", "title": "Religion and Society", "description": "Religion and Society examines how religious ideas, practices, institutions, communities, and identities shape social life, and how social forces reshape religion. The course connects sociology of religion, religious studies, politics, law, race and gender studies, migration studies, media studies, ethics, public policy, and global affairs. Students learn to analyze religion as a lived and public phenomenon using theory, empirical evidence, case studies, and current data.", "topics": [{"id": "c52f89e2-e8b3-4013-bf30-4976bd94a29d", "type": "topic", "title": "Studying Religion and Society: Concepts, Questions, and Methods", "description": "This opening section establishes religion as a social fact, a lived practice, a meaning system, and a public force. Students learn to ask sharper questions than whether religion is simply personal belief.", "children": [{"id": "6166382b-6eaf-44f5-b9bf-f99bd406a9db", "type": "subtopic", "title": "Core concepts", "children": [{"id": "0cca1380-f76c-4ce4-afab-fff9563fe09f", "type": "concept", "title": "Institution and practice"}, {"id": "b2e4d3d4-77b4-448f-a334-ed27c62af5fe", "type": "concept", "title": "Belonging and identity"}, {"id": "80ec318a-875a-4978-959e-24585dd96c54", "type": "concept", "title": "Public and private religion"}], "description": "Students build the vocabulary needed to analyze religion in social life without collapsing it into doctrine alone."}, {"id": "8d3134ef-7649-4f77-8a7a-c6e5237c7c7f", "type": "subtopic", "title": "Levels of analysis", "children": [{"id": "5c62d0bb-4e1d-4dd6-9a9c-707b3c0d36b0", "type": "concept", "title": "Micro interaction"}, {"id": "fb1dc0b7-1987-4cd5-88c7-51abafd8cc70", "type": "concept", "title": "Organizations and fields"}, {"id": "62f94284-637d-40ef-a8aa-9412e66d68f1", "type": "concept", "title": "National and transnational systems"}], "description": "The course moves between individuals, congregations, communities, media systems, states, markets, and global networks."}, {"id": "f19e5002-cb52-4825-819f-e74e39d0db94", "type": "subtopic", "title": "Evidence and method", "children": [{"id": "2db3739d-1c2f-4e8e-8fe8-3a15a5c43fdf", "type": "concept", "title": "Survey data"}, {"id": "6905663e-38e4-4efd-9ca5-7f6f35f67136", "type": "concept", "title": "Field observation"}, {"id": "70e600e0-29ea-4dce-beb4-79e98f25d10d", "type": "concept", "title": "Comparative case studies"}], "description": "Students learn how claims about religion and society are supported through surveys, ethnography, history, archives, and media analysis."}]}, {"id": "e5d3fb1c-e606-44e7-ac30-c6442808d268", "type": "topic", "title": "Classical and Contemporary Social Theories of Religion", "description": "Theory gives students portable tools for interpreting cases. This section connects classic sociology with newer approaches to race, gender, colonialism, practice, and globalization.", "children": [{"id": "17635be0-bf9d-4529-b07c-550a51ab56e3", "type": "subtopic", "title": "Classical theory", "children": [{"id": "52aed90d-2c52-46e4-8a45-b64e04ce6410", "type": "concept", "title": "Durkheim and solidarity"}, {"id": "8e328962-048a-4db7-9da2-c3b3ff7c14f7", "type": "concept", "title": "Weber and rationalization"}, {"id": "30beff40-5a3d-46c9-87a3-daa8f382085a", "type": "concept", "title": "Marx and ideology"}], "description": "Students examine how major theorists explained religion's social functions, conflicts, and relationship to modernity."}, {"id": "ee70004b-445f-402f-8a04-1fe773db4968", "type": "subtopic", "title": "Power and critique", "children": [{"id": "f33ce1df-b4ad-4e7c-a0b6-cca5e212a1b6", "type": "concept", "title": "Du Bois and racialized modernity"}, {"id": "709d460a-e51e-41ac-96fe-8c0bda834103", "type": "concept", "title": "Feminist theory"}, {"id": "2b9062bc-0d87-46f6-942d-e1b8a703e63a", "type": "concept", "title": "Postcolonial critique"}], "description": "Students learn how theories change when race, empire, caste, gender, and colonial knowledge become central."}, {"id": "54d572d0-5b23-4c84-957e-2a6e78d24967", "type": "subtopic", "title": "Contemporary approaches", "children": [{"id": "f36372c2-0436-49d0-9f5c-1d080cd77687", "type": "concept", "title": "Lived religion"}, {"id": "7f411c99-77d3-4824-814e-bbe5c2ad63e5", "type": "concept", "title": "Religious economies"}, {"id": "1f3f891c-826f-4e5a-bcb3-57a7a9bb7c37", "type": "concept", "title": "Bourdieu and fields"}], "description": "Students compare lived religion, rational choice, field theory, cultural sociology, and network approaches."}]}, {"id": "6abf7b0a-a285-4002-9f23-bc8200eb88ed", "type": "topic", "title": "Secularization, Desecularization, and Public Religion", "description": "Modern societies do not all become secular in the same way. This section teaches students to distinguish institutional differentiation, declining affiliation, public religion, and new forms of nonreligion.", "children": [{"id": "899d0f04-0491-43cf-a958-469ea3c36c3b", "type": "subtopic", "title": "Secularization theories", "children": [{"id": "df9e7ad4-8124-49a2-8677-36a8f0a02480", "type": "concept", "title": "Decline thesis"}, {"id": "f24a5cb0-239d-4476-bb04-07b2af8e0aa6", "type": "concept", "title": "Differentiation"}, {"id": "f2966b22-8d72-4f76-b0f5-70be12e8a5e2", "type": "concept", "title": "Privatization"}], "description": "Students learn the major claims about religious decline, privatization, differentiation, and modernization."}, {"id": "f9ea72f6-140b-4f21-8c13-67fe2ecf46f8", "type": "subtopic", "title": "Public religion", "children": [{"id": "e493e21a-80a0-4496-aeb3-7ffcbd57de0e", "type": "concept", "title": "Civil society"}, {"id": "c34df8ec-3a60-4d75-8c76-8251aedde653", "type": "concept", "title": "Public theology"}, {"id": "937533c8-0ba0-4eb2-b827-a722167e6982", "type": "concept", "title": "Religious advocacy"}], "description": "The section studies religion in courts, elections, protest, welfare, education, media, and public rituals."}, {"id": "3d361fae-edaf-458f-99ff-add808214d79", "type": "subtopic", "title": "Nonreligion and spiritual change", "children": [{"id": "8bb3aad6-5609-47bf-ab09-eb0fe16bc71f", "type": "concept", "title": "Nones"}, {"id": "f9f58076-ae5d-48f6-bf20-d5b1b57bc9d0", "type": "concept", "title": "Spiritual but not religious"}, {"id": "ecc9fa49-fddb-4e93-a7cb-a4d9f2055aec", "type": "concept", "title": "Secular identities"}], "description": "Students analyze atheism, agnosticism, secular humanism, spirituality, and the growth of unaffiliated populations."}]}, {"id": "32a8b318-f8e5-4b3c-8480-292e81777bd0", "type": "topic", "title": "Religious Organizations, Authority, Congregations, and Social Capital", "description": "Religious life is organized through institutions, networks, and leadership structures. Students learn how these organizations create belonging, resources, authority, and conflict.", "children": [{"id": "1901bda5-28c9-4562-ad9a-36886d077e75", "type": "subtopic", "title": "Congregations and denominations", "children": [{"id": "911acfeb-9558-4815-a96c-02805c0d8a91", "type": "concept", "title": "Membership and participation"}, {"id": "18a60b84-8499-40a4-b206-d4c0a6effe6c", "type": "concept", "title": "Denominational systems"}, {"id": "bd9cc5b4-0f73-4ecb-b996-513cd2b1d251", "type": "concept", "title": "Local leadership"}], "description": "Students examine congregations as local institutions embedded in neighborhoods, class structures, race, migration, and politics."}, {"id": "c4792409-c10c-4d8f-85fd-af4dc10d1180", "type": "subtopic", "title": "Authority and legitimacy", "children": [{"id": "ddc1719f-ba93-410c-b824-758371d4b6a9", "type": "concept", "title": "Charisma and bureaucracy"}, {"id": "49f9d11f-ad84-4df2-a35c-385a4d02182e", "type": "concept", "title": "Textual authority"}, {"id": "09d246e3-7ddd-49e7-882a-8c47c4b8dcd5", "type": "concept", "title": "Gendered leadership"}], "description": "Students study how authority is claimed through charisma, office, scripture, expertise, lineage, law, and community recognition."}, {"id": "9159c4db-0c86-46c3-99cb-6e7b95bb1d8c", "type": "subtopic", "title": "Social capital and service", "children": [{"id": "12563060-5211-43ab-832f-6080eae54d5d", "type": "concept", "title": "Bonding and bridging capital"}, {"id": "9560b415-362a-4f4b-be5f-33064e7a6b3b", "type": "concept", "title": "Volunteer networks"}, {"id": "e005a196-4ad7-4187-92f1-cbe5d97d637f", "type": "concept", "title": "Faith-based social services"}], "description": "The section studies trust, volunteering, mutual aid, schools, hospitals, charities, and faith-based nonprofits."}]}, {"id": "91995897-b468-4d46-ba62-ee0c4e50876d", "type": "topic", "title": "Religion, State, Law, and Religious Freedom", "description": "States define, protect, manage, and sometimes restrict religion. This section gives students tools for analyzing law without assuming that legal definitions are neutral.", "children": [{"id": "37ce1ec2-4802-46cf-aaf1-e35dad75e78f", "type": "subtopic", "title": "Religion and constitutional order", "children": [{"id": "2268fb2a-5d5f-4b3a-aeb8-e731b4637d4f", "type": "concept", "title": "Free exercise"}, {"id": "41bcc860-a78f-4814-ab9a-82c9efa92014", "type": "concept", "title": "Establishment"}, {"id": "9a871327-d943-47a9-8565-ef141664e6e6", "type": "concept", "title": "Laicite and secularism"}], "description": "Students compare church-state arrangements, secularism, establishment, free exercise, and state neutrality."}, {"id": "7b156e55-741a-4277-a6fb-3b4be17237cc", "type": "subtopic", "title": "Minority rights and regulation", "children": [{"id": "52aecc99-e064-4f42-8e39-7d6d1946eea0", "type": "concept", "title": "Accommodation"}, {"id": "e7a11a62-130c-4199-8fc7-78a5a27b55a4", "type": "concept", "title": "Zoning and sacred space"}, {"id": "35db07cf-8e47-4579-81e0-bacdc2f8efc7", "type": "concept", "title": "Prison and workplace religion"}], "description": "Students study how law treats dress, diet, education, land use, prisons, workplaces, and ritual practices."}, {"id": "d0538c8b-08af-4879-bfbe-133e94c4dd82", "type": "subtopic", "title": "Global religious freedom", "children": [{"id": "47d9e8da-d4a2-4904-9586-23ffc925d17f", "type": "concept", "title": "International norms"}, {"id": "dac045b6-cf27-414e-accf-b6d046e5948a", "type": "concept", "title": "Blasphemy and apostasy laws"}, {"id": "de54a976-4bb8-4356-9076-a16e443ce41d", "type": "concept", "title": "Human rights reporting"}], "description": "The section uses international reports and cases to analyze rights, persecution, security, diplomacy, and advocacy."}]}, {"id": "591fa45b-1feb-4ce5-af69-2cc77aa17142", "type": "topic", "title": "Religion, Politics, Nationalism, Civil Religion, and Populism", "description": "Religion often provides political language, identities, symbols, and institutions. Students learn to analyze public religion without assuming it is always democratic or always dangerous.", "children": [{"id": "e7218761-0830-4967-a56f-77855451b7c6", "type": "subtopic", "title": "Religion and political behavior", "children": [{"id": "dbb3be40-0b56-4ed9-8760-aaa52948ccec", "type": "concept", "title": "Religious voting blocs"}, {"id": "47b16002-2fc5-494b-9323-a1b946b5e944", "type": "concept", "title": "Issue publics"}, {"id": "d99de7c3-3382-4e24-ba76-adb53e411794", "type": "concept", "title": "Clergy and mobilization"}], "description": "Students examine voting, parties, interest groups, policy attitudes, lobbying, and political socialization."}, {"id": "1a96671b-7ff9-4b7a-8fc9-e3265d91abbd", "type": "subtopic", "title": "Nationalism and civil religion", "children": [{"id": "2ae125f7-ddb0-4ede-bb61-2714f4070b6c", "type": "concept", "title": "Civil religion"}, {"id": "2da93e67-4be9-4643-823a-15728cb61c41", "type": "concept", "title": "Sacred nation"}, {"id": "03ea706f-ae1e-4780-829b-9e9ab802ff2a", "type": "concept", "title": "Majoritarian identity"}], "description": "Students analyze sacred narratives of nationhood, memory, sacrifice, monuments, ceremonies, and public myth."}, {"id": "965d0597-fa31-4dd4-bf4f-033e6bb2fe02", "type": "subtopic", "title": "Populism and legitimacy", "children": [{"id": "8449f78d-003e-4e6a-9087-c8246cbe9d95", "type": "concept", "title": "Moral people vs. corrupt elites"}, {"id": "f330c6b8-5ca5-4785-8209-43988b9a1097", "type": "concept", "title": "Charismatic authority"}, {"id": "f3075738-1494-4dd5-96b3-aa46dba24a1e", "type": "concept", "title": "Religious populism"}], "description": "The section studies how religious language can legitimate leaders, opposition movements, and anti-institutional politics."}]}, {"id": "a293394e-0a7f-4226-abef-68b60006d82b", "type": "topic", "title": "Religion, Race, Ethnicity, Caste, Colonialism, and Social Inequality", "description": "Religion is deeply entangled with systems of classification and inequality. Students examine how religion can justify hierarchy and also organize resistance.", "children": [{"id": "40eecad8-84ac-48fe-b962-7acd6ec0b727", "type": "subtopic", "title": "Race and religious formation", "children": [{"id": "39c802ec-4c6d-4479-8348-dc468cba605e", "type": "concept", "title": "Race-making"}, {"id": "9b25c4d8-a8fc-4ec9-8472-9af1cd7b6077", "type": "concept", "title": "Black religious traditions"}, {"id": "f0ccc3bd-7282-4a13-807e-05c482c17cb0", "type": "concept", "title": "Asian, Latino, and Indigenous religious life"}], "description": "Students study racialization, religious identity, slavery, segregation, immigration, whiteness, and minority community formation."}, {"id": "dcd9ed7e-8a1c-42a6-9704-0294bc39f369", "type": "subtopic", "title": "Caste and social hierarchy", "children": [{"id": "88efc458-36a0-405b-97d3-7ff1266c0c66", "type": "concept", "title": "Ritual purity"}, {"id": "bad3db6b-6217-475b-8470-cd7c2ce2f411", "type": "concept", "title": "Social exclusion"}, {"id": "967183f1-abe7-40d2-a59c-cd5cfeac1cc9", "type": "concept", "title": "Anti-caste activism"}], "description": "Students analyze caste, ritual status, reform, law, diaspora, and anti-caste religious movements."}, {"id": "7c161f92-5eea-4f6b-b52b-e895cacf5ae4", "type": "subtopic", "title": "Colonialism and mission", "children": [{"id": "7cf4a305-16a0-4d0c-b838-87916c0d8a52", "type": "concept", "title": "Mission schools"}, {"id": "0a080c46-a589-4349-9974-e4087969d25e", "type": "concept", "title": "Colonial knowledge"}, {"id": "daedc640-0c55-48fe-b358-c5933a3951e7", "type": "concept", "title": "Indigenous sovereignty"}], "description": "The section examines missions, empire, conversion, translation, education, resistance, and postcolonial critique."}]}, {"id": "9407b6db-e433-4b8e-9860-7c0e322cab8c", "type": "topic", "title": "Religion, Gender, Sexuality, Family, and Authority", "description": "Gender and sexuality are central to how religious authority, moral order, family life, and community boundaries are made and contested.", "children": [{"id": "861512ea-eb89-4c0f-a670-a2a26e2e149b", "type": "subtopic", "title": "Gendered institutions", "children": [{"id": "cf3a1d84-86af-4c50-ba12-c3ce1453fc42", "type": "concept", "title": "Women's leadership"}, {"id": "120a1b76-40c5-4e81-aebf-033421041610", "type": "concept", "title": "Clergy and ordination"}, {"id": "dcdae092-06c2-4723-aa25-56db7e737dbf", "type": "concept", "title": "Gendered religious labor"}], "description": "Students study leadership, ritual roles, religious law, education, labor, and institutional exclusion."}, {"id": "bb8de0c4-0166-4393-a211-b20ad0b8fb2a", "type": "subtopic", "title": "Sexuality and family", "children": [{"id": "ab7e6461-d6cb-461a-b2ab-9601fc7b2941", "type": "concept", "title": "Marriage and kinship"}, {"id": "0f450c78-b2b0-4054-b8eb-5486fe70c019", "type": "concept", "title": "Queer religion"}, {"id": "a2f33ee1-8e83-472d-84b6-1dd35f76fc41", "type": "concept", "title": "Reproductive ethics"}], "description": "The section analyzes marriage, divorce, reproduction, LGBTQ+ religious life, family policy, and moral conflict."}, {"id": "91be5733-0cb3-4680-802c-ca6e443a1387", "type": "subtopic", "title": "Embodiment and authority", "children": [{"id": "f28df892-c808-44c5-ade7-b8668d660a16", "type": "concept", "title": "Modesty practices"}, {"id": "3d1b9ba8-ddbe-4213-a1e7-5285849914c9", "type": "concept", "title": "Purity systems"}, {"id": "8abccc15-3e87-4fe3-b851-a961e2dbd05b", "type": "concept", "title": "Body politics"}], "description": "Students examine dress, purity, modesty, bodies, discipline, disability, and contested bodily autonomy."}]}, {"id": "11f1b549-5c8c-40e2-a4a4-13adadd8db2d", "type": "topic", "title": "Religion, Class, Capitalism, Work, Welfare, and Economic Life", "description": "Religion shapes economic behavior and is shaped by markets, labor, inequality, welfare systems, and consumer culture.", "children": [{"id": "05fc1dd4-7b3e-48b0-a858-395cd7d77042", "type": "subtopic", "title": "Religion and capitalism", "children": [{"id": "62e08668-c615-4f98-814f-1c49a1533b89", "type": "concept", "title": "Protestant ethic debates"}, {"id": "3c9a348e-16b0-41ef-9dc7-183b78a951ac", "type": "concept", "title": "Prosperity gospel"}, {"id": "3be35a82-5546-49cc-95ad-115ea88e05fb", "type": "concept", "title": "Religious markets"}], "description": "Students revisit Weber while studying consumer religion, prosperity teachings, discipline, thrift, and market adaptation."}, {"id": "60c8a6e7-9368-43ae-8b75-7dbd9831fa3d", "type": "subtopic", "title": "Poverty, charity, and welfare", "children": [{"id": "b1bd08f1-5af0-4b42-9208-aa98191a57e6", "type": "concept", "title": "Almsgiving and tithing"}, {"id": "37c7f9f3-777c-4fd5-9392-80b7074a5288", "type": "concept", "title": "Faith-based welfare"}, {"id": "851bc180-fb6b-459c-81e4-35afbc5f3fa1", "type": "concept", "title": "Mutual aid"}], "description": "The section asks how religious organizations respond to poverty and how charity relates to justice and policy."}, {"id": "2ba11f1d-5c8b-48c9-b7e2-e61962be1f3b", "type": "subtopic", "title": "Work and economic ethics", "children": [{"id": "fef0e4ac-09e1-46a8-affb-372f6a7c76cc", "type": "concept", "title": "Calling and vocation"}, {"id": "e00ed027-3cd6-4ceb-aa78-16275c9a55e0", "type": "concept", "title": "Debt and usury"}, {"id": "035d988b-670f-4df9-8b88-2609655ad036", "type": "concept", "title": "Labor justice"}], "description": "Students analyze vocation, labor dignity, business ethics, exploitation, debt, finance, and economic inequality."}]}, {"id": "976257f8-e2de-49cd-ac71-ad316a2ed3b4", "type": "topic", "title": "Migration, Diaspora, Pluralism, Interfaith Encounter, and Urban Religion", "description": "Migration changes religious communities and public landscapes. Students study how pluralism is built, contested, and lived in everyday settings.", "children": [{"id": "ed8623b6-68cd-422a-bf7d-c49038f3c34b", "type": "subtopic", "title": "Diaspora and transnational religion", "children": [{"id": "14e4fef6-862a-4ac0-a1db-2ebeb583d381", "type": "concept", "title": "Remittances and pilgrimage"}, {"id": "fb3ff45e-4d63-4eba-9b32-a6d0b2ed6468", "type": "concept", "title": "Transnational authority"}, {"id": "b9960c10-b399-47ed-8a0c-4f321ca4843a", "type": "concept", "title": "Second-generation religion"}], "description": "Students examine how migrants maintain ties, build institutions, and adapt practices across generations."}, {"id": "5ae3b983-f48e-4162-aa24-f73ad81b7cab", "type": "subtopic", "title": "Pluralism and encounter", "children": [{"id": "df12b3a4-a628-4ddb-b7ec-236b0951baf0", "type": "concept", "title": "Interfaith dialogue"}, {"id": "dad0b277-cbc4-43cb-863b-6de4f809fa63", "type": "concept", "title": "Religious literacy"}, {"id": "04bacf89-0c1d-46e9-a586-2603578a1c36", "type": "concept", "title": "Shared civic space"}], "description": "The section distinguishes diversity from pluralism and studies interfaith work, conflict, cooperation, and civic institutions."}, {"id": "c2ca70cf-a946-4294-87c3-62d8122760f1", "type": "subtopic", "title": "Urban religion", "children": [{"id": "88ccad25-5f70-4d21-911c-608d6027870f", "type": "concept", "title": "Sacred space in cities"}, {"id": "97b6fd07-a314-4ad0-86ab-6efb824cd273", "type": "concept", "title": "Religious economies"}, {"id": "72bdd37b-b3c8-480f-8a84-6bd6994ac8b5", "type": "concept", "title": "Gentrification and displacement"}], "description": "Students analyze storefront churches, mosques, temples, immigrant corridors, zoning conflicts, and neighborhood change."}]}, {"id": "aa5d4b4b-1f5b-4e74-a58e-f086f9d8ae76", "type": "topic", "title": "Media, Popular Culture, Digital Religion, and Public Discourse", "description": "Religion circulates through media. Students learn to study representation, authority, misinformation, entertainment, and digital practice.", "children": [{"id": "0d661eba-96ad-40de-8b27-876a6051a88d", "type": "subtopic", "title": "Religion in news and public discourse", "children": [{"id": "411fbbfe-61fb-4668-8a02-ecc95ecaa553", "type": "concept", "title": "Media framing"}, {"id": "1e47f791-867c-4905-af6e-c6d72677933e", "type": "concept", "title": "Religious literacy gaps"}, {"id": "d383997d-0d1e-49d9-8acf-c163564a7d8a", "type": "concept", "title": "Public expertise"}], "description": "Students analyze framing, moral panic, stereotypes, expertise, source selection, and crisis coverage."}, {"id": "9816036b-b16a-4f29-b2f6-23c29767b09d", "type": "subtopic", "title": "Popular culture", "children": [{"id": "605e90b4-d57b-4fe2-bc91-f5f2f9cd4940", "type": "concept", "title": "Film and television"}, {"id": "c563af70-9e5e-4c35-a238-0ae79095292a", "type": "concept", "title": "Music and ritual emotion"}, {"id": "8b88502f-3bb8-4f91-9190-53f50a1a2b16", "type": "concept", "title": "Celebrity spirituality"}], "description": "The section treats film, music, sports, celebrity, fashion, and fandom as sites where religious symbols gain social meaning."}, {"id": "523b58b0-028b-4baf-99a4-6e124ab7765d", "type": "subtopic", "title": "Digital religion", "children": [{"id": "d1325abb-3fed-4a9d-a41f-3bd12f9814d2", "type": "concept", "title": "Streaming services"}, {"id": "e26eb5a3-01e6-43ff-a473-f48f3674870f", "type": "concept", "title": "Religious influencers"}, {"id": "c5ec07c7-0e08-460d-8b0c-3992fc07e6ba", "type": "concept", "title": "Platform moderation"}], "description": "Students examine online worship, influencers, algorithmic authority, memes, platforms, and networked publics."}]}, {"id": "ac1729d2-6579-472c-87de-aa48cefe1e21", "type": "topic", "title": "Religion, Violence, Peacebuilding, Human Rights, and Social Movements", "description": "This section refuses simple explanations. Students analyze religion as one factor among political, economic, historical, and social dynamics in both violence and peacebuilding.", "children": [{"id": "4035fae6-326e-40fa-b5ee-31769b6fc7ca", "type": "subtopic", "title": "Violence and conflict", "children": [{"id": "e931648e-a0b3-4562-8440-1bb2b548baf4", "type": "concept", "title": "Radicalization claims"}, {"id": "6c2892df-17a9-45a4-84c4-404eab162bf9", "type": "concept", "title": "Communal conflict"}, {"id": "88d30d20-9dea-4714-86d7-4264d5553bb7", "type": "concept", "title": "State repression"}], "description": "Students learn to distinguish ideology, organization, grievance, state violence, communal violence, and media narrative."}, {"id": "dc6dbd48-546b-4fac-bb5a-47c7e8b19115", "type": "subtopic", "title": "Peacebuilding and reconciliation", "children": [{"id": "be31ec90-45e5-48c6-a6a3-6e62604cea77", "type": "concept", "title": "Nonviolent movements"}, {"id": "90851841-eca3-4461-90d3-aae2f6f751d5", "type": "concept", "title": "Truth and reconciliation"}, {"id": "c45b2ce3-0129-4c5f-9c08-ffc08557aca3", "type": "concept", "title": "Interfaith mediation"}], "description": "The section studies nonviolence, mediation, restorative practice, interfaith peacebuilding, and post-conflict repair."}, {"id": "a8a05edb-8727-4c1d-a52b-68758c3c0720", "type": "subtopic", "title": "Religion and human rights", "children": [{"id": "24d6538d-0ebd-4920-9546-4693ed3c22e3", "type": "concept", "title": "Freedom of religion or belief"}, {"id": "ccd9714b-6f81-4e5b-af96-0249b499fd76", "type": "concept", "title": "Gender and rights debates"}, {"id": "184e4f5d-faf5-4a8f-b9ce-2aaa5674b32a", "type": "concept", "title": "Rights advocacy networks"}], "description": "Students evaluate tensions and alliances between religious actors and human rights frameworks."}]}, {"id": "018840f2-5982-484c-b304-4313cb66af51", "type": "topic", "title": "Religion, Health, Medicine, Bioethics, and Care Systems", "description": "Religious communities shape health beliefs, care networks, moral decisions, and institutions. Students study health as a social arena where religion matters deeply.", "children": [{"id": "a60f103d-36f8-485d-bd67-de11647a2ade", "type": "subtopic", "title": "Health beliefs and care", "children": [{"id": "cf0c0936-38e9-475f-8e71-912a3146506e", "type": "concept", "title": "Ritual healing"}, {"id": "cfc9e8ba-fc78-4f95-bd6d-b29042919ca8", "type": "concept", "title": "End-of-life care"}, {"id": "8c08f1dc-1d19-4c35-8ac0-b204292991f4", "type": "concept", "title": "Mental health stigma and support"}], "description": "Students analyze healing, suffering, death, disability, mental health, chaplaincy, and community care."}, {"id": "721ef963-15a6-4490-816a-45390bd307d3", "type": "subtopic", "title": "Bioethics", "children": [{"id": "ba3c2681-00d1-4f42-8996-e3c3a44e0ada", "type": "concept", "title": "Reproductive debates"}, {"id": "baad73b5-3bb8-48c9-8d83-4c557e406484", "type": "concept", "title": "Vaccination and public health"}, {"id": "674b5086-8bbc-4632-bf73-48ab8dd7ea8e", "type": "concept", "title": "Conscience claims"}], "description": "The section examines reproductive ethics, vaccination, organ donation, genetic technology, refusal of care, and medical pluralism."}, {"id": "d3f9ef35-6feb-422e-9a3f-0bec89eeca63", "type": "subtopic", "title": "Faith-based health systems", 