": "Climate justice"}, {"id": "d2b731c2-7f75-4e2f-971e-458458f14c83", "type": "concept", "title": "Faith-based advocacy"}, {"id": "3b4daa72-ad05-419c-995d-78e239586e57", "type": "concept", "title": "Disaster and resilience"}], "description": "Students analyze climate statements, activism, divestment, disaster response, and interfaith environmental coalitions."}]}, {"id": "90301525-fe16-4c67-ba97-161db4e95bb8", "type": "topic", "title": "Research Design, Demographics, Evaluation, and Capstone Public Religion Analysis", "description": "The final section teaches students to produce responsible public analysis. They combine social theory, evidence, data, ethics, and clear communication.", "children": [{"id": "fc10e085-4865-44cb-83b1-36357f3c9972", "type": "subtopic", "title": "Religious demographics and survey data", "children": [{"id": "76b9f0ae-c425-428c-a6bc-1a424d346c15", "type": "concept", "title": "Sampling and question wording"}, {"id": "f6b6e2f6-4a97-4ab5-84d4-22e09df6d682", "type": "concept", "title": "Trend interpretation"}, {"id": "62e0e0f2-77de-41f2-aa0f-f31413404430", "type": "concept", "title": "Cross-tabs and limits"}], "description": "Students learn to read affiliation, attendance, belief, race, age, geography, and trend data critically."}, {"id": "6cbc50bd-a641-402d-b8cc-5285fd4c78d6", "type": "subtopic", "title": "Case-study research design", "children": [{"id": "80fde847-aa02-43a2-b582-3a9f94cd0607", "type": "concept", "title": "Research question"}, {"id": "94e19fff-509f-4cc4-a57a-84b1eac32155", "type": "concept", "title": "Evidence matrix"}, {"id": "11f2e5ce-554f-4446-a477-4ba1f9966c74", "type": "concept", "title": "Case selection"}], "description": "Students develop a focused question, choose evidence, justify methods, and compare cases responsibly."}, {"id": "b96a3015-26f1-424a-b1a4-aa73b701ca14", "type": "subtopic", "title": "Public-facing capstone", "children": [{"id": "0aac3168-e1da-46a8-97ec-aad00d6b6c80", "type": "concept", "title": "Executive summary"}, {"id": "f8dfd2d7-cd2a-4eb3-a5d7-620efac01916", "type": "concept", "title": "Source transparency"}, {"id": "7744b337-1c6a-45df-9ede-501620d5673c", "type": "concept", "title": "Nuanced recommendation or interpretation"}], "description": "Students translate research into a clear memo or presentation for educated non-specialists."}]}], "dbBacked": true}$resjson$::jsonb,
