  ('6166382b-6eaf-44f5-b9bf-f99bd406a9db', 'f4a5b6c7-8d9e-4f39-8c89-9a0b1c2d3e29', 'c52f89e2-e8b3-4013-bf30-4976bd94a29d', 'subtopic'::public.curated_course_node_type, 'Core concepts', 'Students build the vocabulary needed to analyze religion in social life without collapsing it into doctrine alone.', 0),
