  ('70e600e0-29ea-4dce-beb4-79e98f25d10d', 'f4a5b6c7-8d9e-4f39-8c89-9a0b1c2d3e29', 'f19e5002-cb52-4825-819f-e74e39d0db94', 'concept'::public.curated_course_node_type, 'Comparative case studies', null, 2),
