  ('52aed90d-2c52-46e4-8a45-b64e04ce6410', 'f4a5b6c7-8d9e-4f39-8c89-9a0b1c2d3e29', '17635be0-bf9d-4529-b07c-550a51ab56e3', 'concept'::public.curated_course_node_type, 'Durkheim and solidarity', null, 0),
