  ('1f3f891c-826f-4e5a-bcb3-57a7a9bb7c37', 'f4a5b6c7-8d9e-4f39-8c89-9a0b1c2d3e29', '54d572d0-5b23-4c84-957e-2a6e78d24967', 'concept'::public.curated_course_node_type, 'Bourdieu and fields', null, 2),
