  ('ecc9fa49-fddb-4e93-a7cb-a4d9f2055aec', 'f4a5b6c7-8d9e-4f39-8c89-9a0b1c2d3e29', '3d361fae-edaf-458f-99ff-add808214d79', 'concept'::public.curated_course_node_type, 'Secular identities', null, 2),
